// Робот-розвідник: ТІЛЬКИ вхід у веб-клієнт 1С і скріншоти. Жодних записів.
const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const env = {};
  for (const l of fs.readFileSync('/root/unitex-finrep/secure/odata_write.env','utf8').split('\n')) {
    const m = l.match(/^\s*([A-Z_]+)\s*=\s*(.+?)\s*$/); if (m) env[m[1]] = m[2];
  }
  fs.mkdirSync('/root/webbot/shots', { recursive: true });
  const browser = await chromium.launch({ args: ['--no-sandbox'] });
  const ctx = await browser.newContext({ ignoreHTTPSErrors: true, viewport: {width:1280, height:800}, locale: 'uk-UA' });
  const page = await ctx.newPage();
  page.on('dialog', d => d.accept());
  await page.goto('https://unitex.rdport.net:29231/DB/', { waitUntil: 'load', timeout: 60000 });
  await page.waitForTimeout(9000);
  await page.screenshot({ path: '/root/webbot/shots/01-start.png' });
  console.log('TITLE:', await page.title());
  const inputs = await page.$$eval('input', ns => ns.map(n => ({t:n.type, id:n.id, name:n.name, vis:!!(n.offsetWidth||n.offsetHeight)})));
  console.log('INPUTS:', JSON.stringify(inputs).slice(0, 700));
  const user = await page.$('css=input[type="text"]:visible');
  const pass = await page.$('css=input[type="password"]:visible');
  if (user && pass) {
    await user.fill(env.ODATA_USER);
    await pass.fill(env.ODATA_PASS);
    await pass.press('Enter');
    await page.waitForTimeout(15000);
    await page.screenshot({ path: '/root/webbot/shots/03-after-login.png' });
    console.log('AFTER TITLE:', await page.title());
    const text = await page.evaluate(() => document.body.innerText.slice(0, 700));
    console.log('BODY:', text.replace(/\s+/g, ' ').slice(0, 700));
  } else {
    console.log('ПОЛІВ ВХОДУ НЕ ЗНАЙДЕНО');
    const text = await page.evaluate(() => document.body.innerText.slice(0, 700));
    console.log('BODY:', text.replace(/\s+/g, ' ').slice(0, 700));
  }
  await browser.close();
})().catch(e => { console.log('ПОМИЛКА:', String(e).slice(0, 400)); process.exit(1); });
JSEOF
cd /root/webbot && timeout 110 node login_test.js
